		return;
	end
	self.State.GrabbingGun = true;
	task.spawn(function()
		pcall(function()
			local myPos = root.Position;
			local gunPos = handle.Position;
			local dist = (gunPos - myPos).Magnitude;
			pcall(function()
				if handle:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\45\220\3\245\10\200\29\201", "\169\111\189\112\144\90")) then
					handle.CFrame = root.CFrame;
