			p.CastShadow = false;
			local rel = cframeOrigin:ToObjectSpace(item.CFrame);
			p.CFrame = turnFront * rel;
			p.Parent = clone;
		elseif item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\50\60\160\5\93\220\49\1\38", "\94\115\95\195\96\46\175")) then
			local acc = item:Clone();
