Hub.ClearAllESP = function(self)
	for _, h in pairs(self.ESP.Highlights) do
		if h then
			pcall(function()
				h:Destroy();
			end);
		end
	end
	table.clear(self.ESP.Highlights);
	for _, d in pairs(self.ESP.Drawings) do
		if d.Box then
			pcall(function()
				d.Box.Visible = false;
				d.Box:Remove();
			end);
		end
		if d.Tracer then
			pcall(function()
				d.Tracer.Visible = false;
				d.Tracer:Remove();
			end);
		end
	end
	table.clear(self.ESP.Drawings);
	for _, p in ipairs(self.Services.Players:GetPlayers()) do
		local char = p.Character;
		if char then
			local bg = char:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\27\33\37\0\36\63\248\28\2\3\103", "\67\86\108\23\95\97\108\168"));
