		if (votes ~= "") then
			self.Maps.Cached[padName].Votes = votes;
		end
		if (imageId ~= "") then
			self.Maps.Cached[padName].Image = imageId;
		end
		table.insert(result, {PadName=padName,Pad=pad,MapName=self.Maps.Cached[padName].MapName,Votes=self.Maps.Cached[padName].Votes,Image=self.Maps.Cached[padName].Image});
