Hub.DetectDevice = function(self)
	local uis = self.Services.UserInputService;
	local cam = self.Services.Workspace.CurrentCamera;
	local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720);
	local devType = LUAOBFUSACTOR_DECRYPT_STR_0("\51\194\242\193\3\200\241", "\170\119\167\129");
	local isTouch = uis.TouchEnabled;
	if (uis.TouchEnabled and not uis.KeyboardEnabled) then
		local minDim = math.min(vp.X, vp.Y);
		local maxDim = math.max(vp.X, vp.Y);
		if ((minDim < 540) or (maxDim < 860)) then
			devType = "Mobile";
		else
			devType = "Tablet";
		end
	elseif (uis.GamepadEnabled and not uis.KeyboardEnabled and not uis.MouseEnabled) then
		devType = "Console";
	elseif (uis.TouchEnabled and (vp.X < 920)) then
		devType = "Mobile";
	elseif (uis.TouchEnabled and (vp.X < 1200)) then
		devType = "Tablet";
	else
		devType = LUAOBFUSACTOR_DECRYPT_STR_0("\254\245\175\120\151\81\202", "\62\186\144\220\19\227");
	end
	self.State.Device = {Type=devType,IsTouch=isTouch,Viewport=vp,IsMobile=(devType == "Mobile"),[LUAOBFUSACTOR_DECRYPT_STR_0("\136\239\216\215\163\240\233\194", "\182\193\156\140")]=(devType == LUAOBFUSACTOR_DECRYPT_STR_0("\245\77\20\190\227\43", "\95\161\44\118\210\134")),[LUAOBFUSACTOR_DECRYPT_STR_0("\207\83\48\2\116\197\234\162\227", "\206\134\32\115\109\26\182\133")]=(devType == LUAOBFUSACTOR_DECRYPT_STR_0("\21\247\193\0\82\81\51", "\61\86\152\175\115\61")),IsDesktop=(devType == "Desktop")};
	return self.State.Device;
end;
Hub.GetAdaptiveWindowSize = function(self)
	local dev = self.State.Device or self:DetectDevice();
	local cam = self.Services.Workspace.CurrentCamera;
	local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720);
	if dev.IsMobile then
		local w = math.clamp(math.floor(vp.X * 0.94), 320, 560);
		local h = math.clamp(math.floor(vp.Y * 0.9), 280, 390);
		return UDim2.new(0, w, 0, h), UDim2.new(0, w + 30, 0, h + 30);
	elseif dev.IsTablet then
		local w = math.clamp(math.floor(vp.X * 0.85), 560, 680);
		local h = math.clamp(math.floor(vp.Y * 0.82), 380, 480);
		return UDim2.new(0, w, 0, h), UDim2.new(0, w + 40, 0, h + 40);
	else
		local w = math.min(720, math.floor(vp.X - 60));
		local h = math.min(500, math.floor(vp.Y - 60));
		return UDim2.new(0, w, 0, h), UDim2.new(0, w + 40, 0, h + 40);
	end
end;
