		clickCatcher.Size = UDim2.new(1, 0, 1, -34);
		clickCatcher.BackgroundTransparency = 1;
		clickCatcher.Text = "";
		clickCatcher.Parent = card;
		clickCatcher.MouseButton1Click:Connect(handleCardClick);
